        let signature = try XCTUnwrap(request.headers["x-signature"])
        XCTAssertEqual(signature, try TungoWebhooks.hookSignatureHeader(body: body, secret: "hook-secret"))
        XCTAssertTrue(signature.hasPrefix("sha256="))
