    func testHookSignatureGoesToTheHeaderTheHookNames() async throws {
        server.enqueue(.json(202, Fixture.hookAccepted), .json(202, Fixture.hookAccepted))
        let body = Data(#"{"order":1}"#.utf8)
        _ = try await makeClient().sendHook(token: "tok", body: body, secret: "hook-secret", signatureHeader: "X-Hub-Signature-256")
        struct Order: Encodable { let order: Int }
        _ = try await makeClient().sendHook(token: "tok", payload: Order(order: 1), secret: "hook-secret", signatureHeader: "X-Shop-Sign")
        let requests = server.requests
        XCTAssertEqual(requests.count, 2)
        XCTAssertEqual(requests[0].headers["x-hub-signature-256"], try TungoWebhooks.hookSignatureHeader(body: body, secret: "hook-secret"))
        XCTAssertNil(requests[0].headers["x-signature"])
        XCTAssertEqual(requests[1].headers["x-shop-sign"], try TungoWebhooks.hookSignatureHeader(body: body, secret: "hook-secret"))
        XCTAssertNil(requests[1].headers["x-signature"])

        for bad in ["", "X Signature", "X-Sig\r\nX-Api-Key: 1", "Подпись", String(repeating: "a", count: 65)] {
            await assertThrows(
                try await makeClient().sendHook(token: "tok", body: body, secret: "hook-secret", signatureHeader: bad), bad
