    func testVerifyWebhookUsesTheClientSecret() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "vectors", withExtension: "json"))
        let vectors = try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url))
        let cases = try XCTUnwrap(vectors["webhook_verification"]?["cases"]?.arrayValue)
        let valid = try XCTUnwrap(cases.first { $0["expect"]?["valid"] == true && $0["tolerance_seconds"] == nil })
        var headers: [String: String] = [:]
        for (name, value) in valid["headers"]?.objectValue ?? [:] { headers[name] = value.stringValue }
        let body = Data(try XCTUnwrap(valid["body"]?.stringValue).utf8)
        let now = Date(timeIntervalSince1970: try XCTUnwrap(valid["now"]?.doubleValue))
        let secret = try XCTUnwrap(valid["secret"]?.stringValue)

        let event = try makeClient(webhookSecret: secret).verifyWebhook(body: body, headers: headers, now: now)
        XCTAssertEqual(event.typeTag, valid["expect"]?["event_type"]?.stringValue)

        XCTAssertThrowsError(try makeClient().verifyWebhook(body: body, headers: headers, now: now)) { error in
            XCTAssertEqual((error as? WebhookVerificationError)?.reason, .invalidSecret)
        }
        XCTAssertThrowsError(try makeClient(webhookSecret: secret).verifyWebhook(body: body + Data([0x20]), headers: headers, now: now)) { error in
            XCTAssertEqual((error as? WebhookVerificationError)?.reason, .signatureMismatch)
        }
    }

